"use client";
import Link from "next/link";
import { useState } from "react";
import { useFavorites } from "@/lib/favorites";

type Item = { slug: string; title: string; author: string; year: number; tags: string[] };

export default function BookList({ books, tags }: { books: Item[]; tags: string[] }) {
  const [tag, setTag] = useState<string | null>(null);
  const favs = useFavorites();
  return (
    <>
      <div role="group" aria-label="Filter by tag">
        <button type="button" aria-pressed={tag === null} onClick={() => setTag(null)}>
          All
        </button>
        {tags.map((t) => (
          <button key={t} type="button" aria-pressed={tag === t} onClick={() => setTag(t)}>
            {t}
          </button>
        ))}
      </div>
      <ul aria-label="Books">
        {books
          .filter((b) => tag === null || b.tags.includes(tag))
          .map((b) => (
            <li key={b.slug}>
              <Link href={`/books/${b.slug}`}>{b.title}</Link>{" "}
              <span>
                {b.author}, {b.year}
              </span>
              {favs.includes(b.slug) && <> <strong>Favorite</strong></>}
            </li>
          ))}
      </ul>
    </>
  );
}
