export type ContactState = {
  values: { name: string; email: string; message: string };
  errors: { name?: string; email?: string; message?: string };
  success?: string;
};

export function validate(raw: { name: string; email: string; message: string }): ContactState {
  const values = {
    name: raw.name.trim(),
    email: raw.email.trim(),
    message: raw.message.trim(),
  };
  const errors: ContactState["errors"] = {};
  if (!values.name) errors.name = "Name is required.";
  if (!values.email) errors.email = "Email is required.";
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email))
    errors.email = "Enter a valid email address.";
  if (values.message.length < 20) errors.message = "Message must be at least 20 characters.";
  const ok = Object.keys(errors).length === 0;
  return {
    values,
    errors,
    success: ok ? `Thanks, ${values.name}! Your message has been sent.` : undefined,
  };
}
