"use client";
import { useActionState } from "react";
import { validate, type ContactState } from "@/lib/contact";
import { send } from "./actions";

async function action(prev: ContactState | null, fd: FormData): Promise<ContactState> {
  const s = (k: string) => String(fd.get(k) ?? "");
  const local = validate({ name: s("name"), email: s("email"), message: s("message") });
  if (!local.success) return local;
  return send(prev, fd);
}

export default function ContactForm() {
  const [state, formAction] = useActionState(action, null);
  return (
    <form action={formAction} noValidate>
      {state?.success && <p role="status">{state.success}</p>}
      <div>
        <label htmlFor="name">Name</label>
        <input id="name" name="name" type="text" defaultValue={state?.success ? "" : state?.values.name} />
        {state?.errors.name && <span>{state.errors.name}</span>}
      </div>
      <div>
        <label htmlFor="email">Email</label>
        <input id="email" name="email" type="email" defaultValue={state?.success ? "" : state?.values.email} />
        {state?.errors.email && <span>{state.errors.email}</span>}
      </div>
      <div>
        <label htmlFor="message">Message</label>
        <textarea id="message" name="message" defaultValue={state?.success ? "" : state?.values.message} />
        {state?.errors.message && <span>{state.errors.message}</span>}
      </div>
      <button type="submit">Send</button>
    </form>
  );
}
